export function drawOverlay(ctx, model) {
  clearLayer(ctx);
  const crease = new Path2D();
  crease.moveTo(362, 739);
  crease.bezierCurveTo(392, 744, 420, 745, 450, 746);
  crease.bezierCurveTo(480, 745, 508, 744, 538, 739);
