export class SoundKit {
  constructor(enabled = true) {
    this.enabled = enabled;
    this.ctx = null;
  }

  ensure() {
    if (!this.enabled) return null;
    if (!this.ctx) {
      const AudioCtx = window.AudioContext || window.webkitAudioContext;
      if (!AudioCtx) return null;
      this.ctx = new AudioCtx();
    }
    if (this.ctx.state === 'suspended') this.ctx.resume().catch(() => {});
    return this.ctx;
  }

  tone({ frequency = 440, duration = 0.09, type = 'sine', gain = 0.05, slide = 0, delay = 0 }) {
    const ctx = this.ensure();
    if (!ctx) return;
    const start = ctx.currentTime + delay;
    const osc = ctx.createOscillator();
    const amp = ctx.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(frequency, start);
    if (slide) osc.exponentialRampToValueAtTime(Math.max(40, frequency + slide), start + duration);
    amp.gain.setValueAtTime(0.0001, start);
    amp.gain.exponentialRampToValueAtTime(gain, start + 0.012);
    amp.gain.exponentialRampToValueAtTime(0.0001, start + duration);
    osc.connect(amp).connect(ctx.destination);
    osc.start(start);
    osc.stop(start + duration + 0.02);
  }

  click() {
    this.tone({ frequency: 660, duration: 0.055, type: 'triangle', gain: 0.028, slide: -80 });
  }

  select() {
    this.tone({ frequency: 520, duration: 0.08, type: 'sine', gain: 0.04 });
    this.tone({ frequency: 780, duration: 0.1, type: 'sine', gain: 0.03, delay: 0.045 });
  }

  swipe() {
    this.tone({ frequency: 900, duration: 0.06, type: 'sine', gain: 0.014, slide: -300 });
  }

  success(stars = 3) {
    const notes = stars >= 3 ? [523.25, 659.25, 783.99, 1046.5] : stars === 2 ? [523.25, 659.25, 783.99] : [440, 554.37];
    notes.forEach((frequency, index) => {
      this.tone({ frequency, duration: 0.28, type: 'sine', gain: 0.045, delay: index * 0.11 });
      this.tone({ frequency: frequency * 2, duration: 0.2, type: 'triangle', gain: 0.014, delay: index * 0.11 });
    });
  }

  softFail() {
    this.tone({ frequency: 330, duration: 0.18, type: 'sine', gain: 0.035, slide: -40 });
    this.tone({ frequency: 262, duration: 0.25, type: 'sine', gain: 0.03, delay: 0.12, slide: -20 });
  }

  pop() {
    this.tone({ frequency: 420, duration: 0.1, type: 'sine', gain: 0.04, slide: 260 });
  }
}

:root {
  --bg: #14070e;
  --bg-2: #1e0b17;
  --panel: rgba(43, 20, 33, 0.72);
  --panel-strong: rgba(52, 24, 41, 0.92);
  --line: rgba(255, 224, 235, 0.12);
  --line-strong: rgba(255, 224, 235, 0.2);
  --cream: #fff4ee;
  --muted: #d4b8c2;
  --muted-2: #a98b97;
  --rose: #ff7b9c;
  --rose-deep: #d94b72;
  --gold: #f1c675;
  --gold-deep: #c9933d;
  --mint: #8fe5cf;
  --violet: #b997ff;
  --danger: #ff8f9f;
  --radius: 22px;
  --shadow: 0 20px 60px rgba(0, 0, 0, 0.4);
  --font-ui: "Inter", "Segoe UI", system-ui, -apple-system, BlinkMacSystemFont, sans-serif;
  --font-display: "Iowan Old Style", "Palatino Linotype", "Book Antiqua", Palatino, Georgia, serif;
}

* {
  box-sizing: border-box;
}

html,
body {
  margin: 0;
  min-height: 100%;
  background: var(--bg);
  color: var(--cream);
  font-family: var(--font-ui);
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

body {
  min-height: 100dvh;
  overflow: hidden;
  background:
    radial-gradient(circle at 12% 0%, rgba(165, 59, 99, 0.28), transparent 38%),
    radial-gradient(circle at 100% 20%, rgba(91, 58, 134, 0.24), transparent 36%),
    radial-gradient(circle at 50% 110%, rgba(217, 75, 114, 0.14), transparent 48%),
    linear-gradient(155deg, #190811, #10060c 52%, #1a0912);
}

body::before {
  content: "";
  position: fixed;
  inset: 0;
  pointer-events: none;
  opacity: 0.28;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='0.18'/%3E%3C/svg%3E");
  z-index: 0;
}

button,
input {
  font: inherit;
}

button {
  color: inherit;
  cursor: pointer;
}

button:focus-visible,
input:focus-visible {
  outline: 2px solid var(--gold);
  outline-offset: 3px;
}

button:disabled {
  cursor: default;
  opacity: 0.35;
}

.hidden,
[hidden] {
  display: none !important;
}

.app {
  position: relative;
  z-index: 1;
  display: flex;
  flex-direction: column;
  height: 100dvh;
}

/* ---------- Top bar ---------- */

.topbar {
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  height: 66px;
  padding: 0 22px;
  border-bottom: 1px solid rgba(255, 224, 235, 0.08);
  background: linear-gradient(180deg, rgba(24, 9, 17, 0.88), rgba(24, 9, 17, 0.28));
  backdrop-filter: blur(14px);
}

.brand {
  display: inline-flex;
  align-items: center;
  gap: 11px;
  border: 0;
  background: none;
  padding: 6px 4px;
}

.brand-mark {
  display: grid;
  place-items: center;
  width: 39px;
  height: 39px;
  border-radius: 13px;
  color: #3a0d20;
  background: linear-gradient(145deg, #ffe0b5, #f1c675 40%, #e995aa);
  box-shadow: 0 5px 20px rgba(241, 198, 117, 0.2), inset 0 1px 0 rgba(255, 255, 255, 0.6);
}

.brand-mark svg {
  width: 25px;
  height: 25px;
}

.brand-text {
  font-family: var(--font-display);
  font-size: 21px;
  letter-spacing: 0.02em;
  color: #fff1ea;
}

.brand-text b {
  color: var(--gold);
  font-weight: 600;
}

.topbar-stats {
  display: flex;
  align-items: center;
  gap: 8px;
}

.stat-chip {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  height: 34px;
  padding: 0 12px;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: rgba(255, 243, 238, 0.045);
  color: #ffeadf;
  font-size: 13px;
  font-weight: 600;
  letter-spacing: 0.02em;
}

.star-ico {
  color: var(--gold);
  font-size: 15px;
  filter: drop-shadow(0 0 6px rgba(241, 198, 117, 0.4));
}

.coin-ico {
  display: grid;
  place-items: center;
  width: 17px;
  height: 17px;
  border-radius: 50%;
  background: linear-gradient(145deg, #ffe1a1, #d49a3a);
  color: #5a360c;
  font-size: 9px;
  font-weight: 800;
}

.progress-chip {
  gap: 5px;
  color: var(--muted);
}

.progress-chip #challengeProgress {
  color: var(--cream);
  font-weight: 700;
}

.progress-label {
  font-weight: 500;
  color: var(--muted-2);
}

.icon-button {
  display: grid;
  place-items: center;
  width: 38px;
  height: 38px;
  padding: 0;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: rgba(255, 244, 238, 0.04);
  color: #f6ded8;
  transition: background 0.2s, border-color 0.2s, transform 0.2s;
}

.icon-button:hover {
  background: rgba(255, 244, 238, 0.1);
  border-color: var(--line-strong);
}

.icon-button:active {
  transform: scale(0.94);
}

.icon-button svg {
  width: 19px;
  height: 19px;
}

.icon-button.small {
  width: 32px;
  height: 32px;
  border-radius: 10px;
}

.icon-button.small svg {
  width: 16px;
  height: 16px;
}

.icon-button.muted .sound-wave,
.icon-button.muted .sound-wave2 {
  opacity: 0.18;
}

/* ---------- Studio layout ---------- */

.studio {
  flex: 1 1 auto;
  display: grid;
  grid-template-columns: 276px minmax(0, 1fr) 330px;
  gap: 14px;
  width: 100%;
  max-width: 1680px;
  min-height: 0;
  margin: 0 auto;
  padding: 14px 20px 18px;
}

.panel {
  min-height: 0;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background:
    radial-gradient(circle at 20% 0%, rgba(255, 123, 156, 0.09), transparent 42%),
    linear-gradient(155deg, rgba(55, 26, 43, 0.76), rgba(31, 12, 23, 0.84));
  box-shadow: 0 16px 44px rgba(0, 0, 0, 0.2), inset 0 1px 0 rgba(255, 255, 255, 0.05);
  backdrop-filter: blur(18px);
  padding: 17px;
  overflow: auto;
  scrollbar-width: thin;
  scrollbar-color: rgba(255, 224, 235, 0.2) transparent;
}

.panel::-webkit-scrollbar,
.modal-card::-webkit-scrollbar {
  width: 7px;
}

.panel::-webkit-scrollbar-thumb,
.modal-card::-webkit-scrollbar-thumb {
  border-radius: 99px;
  background: rgba(255, 224, 235, 0.17);
}

.panel-heading {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  margin-bottom: 13px;
}

.panel-kicker {
  margin: 0 0 3px;
  color: var(--gold);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.2em;
  text-transform: uppercase;
}

.panel-heading h2,
.palette-heading h3,
.modal-head h2 {
  margin: 0;
  font-family: var(--font-display);
  font-weight: 500;
  letter-spacing: 0.01em;
}

.panel-heading h2 {
  font-size: 23px;
}

.panel-spark {
  color: var(--rose);
  font-size: 17px;
  animation: softPulse 3.4s ease-in-out infinite;
}

.tool-tabs {
  display: flex;
  gap: 4px;
  padding: 4px;
  margin-bottom: 12px;
  border: 1px solid rgba(255, 224, 235, 0.08);
  border-radius: 13px;
  background: rgba(19, 7, 14, 0.38);
}

.tool-tab {
  flex: 1;
  padding: 7px 2px;
  border: 0;
  border-radius: 9px;
  background: transparent;
  color: var(--muted-2);
  font-size: 10.5px;
  font-weight: 600;
  letter-spacing: 0.02em;
  transition: color 0.2s, background 0.2s;
}

.tool-tab:hover {
  color: var(--cream);
}

.tool-tab.is-active {
  color: #2d0c18;
  background: linear-gradient(145deg, #ffe4ba, #f1c675);
  box-shadow: 0 4px 14px rgba(241, 198, 117, 0.18);
}

.tool-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 7px;
  margin-bottom: 16px;
}

.tool-tile {
  position: relative;
  display: flex;
  align-items: center;
  gap: 8px;
  min-height: 59px;
  padding: 9px 9px;
  border: 1px solid rgba(255, 224, 235, 0.1);
  border-radius: 13px;
  background: rgba(255, 244, 238, 0.035);
  color: #f0d8d9;
  text-align: left;
  transition: transform 0.18s, border-color 0.18s, background 0.18s, box-shadow 0.18s;
}

.tool-tile:hover {
  border-color: rgba(255, 224, 235, 0.24);
  background: rgba(255, 244, 238, 0.07);
  transform: translateY(-1px);
}

.tool-tile.is-active {
  border-color: rgba(255, 123, 156, 0.7);
  background: linear-gradient(150deg, rgba(255, 123, 156, 0.2), rgba(255, 123, 156, 0.06));
  box-shadow: inset 0 0 0 1px rgba(255, 123, 156, 0.14), 0 8px 22px rgba(89, 20, 47, 0.22);
}

.tool-icon {
  display: grid;
  place-items: center;
  flex: 0 0 auto;
  width: 31px;
  height: 31px;
  border-radius: 10px;
  background: rgba(255, 244, 238, 0.07);
  color: #ffd5dd;
}

.tool-tile.is-active .tool-icon {
  background: rgba(255, 123, 156, 0.19);
  color: #ffb6c7;
}

.tool-icon svg {
  width: 19px;
  height: 19px;
}

.tool-name {
  font-size: 11.5px;
  font-weight: 600;
  line-height: 1.15;
}

.tool-sub {
  display: block;
  margin-top: 2px;
  color: var(--muted-2);
  font-size: 9px;
  font-weight: 500;
}

.brush-controls {
  padding: 13px 2px 2px;
  border-top: 1px solid var(--line);
}

.control-heading {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  margin-bottom: 10px;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.03em;
}

.control-readout {
  color: var(--gold);
  font-variant-numeric: tabular-nums;
  font-size: 10px;
}

.slider-label {
  display: block;
  margin: 8px 0 5px;
  color: var(--muted-2);
  font-size: 9px;
  font-weight: 600;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

input[type="range"] {
  width: 100%;
  height: 18px;
  margin: 0;
  appearance: none;
  background: transparent;
}

input[type="range"]::-webkit-slider-runnable-track {
  height: 4px;
  border-radius: 99px;
  background: linear-gradient(90deg, rgba(255, 123, 156, 0.7), rgba(241, 198, 117, 0.6));
}

input[type="range"]::-moz-range-track {
  height: 4px;
  border-radius: 99px;
  background: linear-gradient(90deg, rgba(255, 123, 156, 0.7), rgba(241, 198, 117, 0.6));
}

input[type="range"]::-webkit-slider-thumb {
  appearance: none;
  width: 15px;
  height: 15px;
  margin-top: -5.5px;
  border: 2px solid #fff1e8;
  border-radius: 50%;
  background: #a83b5e;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.4);
}

input[type="range"]::-moz-range-thumb {
  width: 12px;
  height: 12px;
  border: 2px solid #fff1e8;
  border-radius: 50%;
  background: #a83b5e;
}

.tool-hint {
  margin: 12px 0 0;
  padding: 10px 11px;
  border: 1px solid rgba(255, 224, 235, 0.08);
  border-radius: 12px;
  background: rgba(16, 5, 11, 0.25);
  color: #c7aab5;
  font-size: 10px;
  line-height: 1.55;
}

/* ---------- Stage ---------- */

.stage-wrap {
  min-width: 0;
  min-height: 0;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.stage-card {
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: column;
  border: 1px solid rgba(255, 224, 235, 0.13);
  border-radius: 26px;
  background:
    radial-gradient(ellipse at 50% 30%, rgba(255, 146, 176, 0.11), transparent 52%),
    linear-gradient(165deg, rgba(48, 20, 36, 0.78), rgba(17, 6, 12, 0.9));
  box-shadow: 0 28px 80px rgba(0, 0, 0, 0.42), inset 0 1px 0 rgba(255, 255, 255, 0.06);
  padding: 12px;
  overflow: hidden;
}

.stage-topbar {
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  padding: 1px 4px 9px;
}

.live-badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
  padding: 7px 12px;
  border: 1px solid rgba(255, 224, 235, 0.11);
  border-radius: 999px;
  background: rgba(16, 5, 11, 0.32);
  color: #f5dfe0;
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.04em;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.live-dot {
  width: 6px;
  height: 6px;
  flex: 0 0 auto;
  border-radius: 50%;
  background: var(--rose);
  box-shadow: 0 0 0 4px rgba(255, 123, 156, 0.12);
  animation: softPulse 2.2s ease-in-out infinite;
}

.stage-actions {
  display: flex;
  align-items: center;
  gap: 6px;
}

.face-shell {
  position: relative;
  flex: 1;
  min-height: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 0 4px;
}

.face-scene {
  position: relative;
  height: 100%;
  width: auto;
  aspect-ratio: 900 / 1150;
  max-width: 100%;
  max-height: 100%;
  border-radius: 20px;
  overflow: hidden;
  background: #1c0812;
  box-shadow:
    0 24px 60px rgba(0, 0, 0, 0.5),
    0 0 0 1px rgba(255, 223, 234, 0.14),
    inset 0 0 60px rgba(0, 0, 0, 0.2);
  isolation: isolate;
}

.face-scene canvas {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
}

.face-scene canvas.interaction {
  z-index: 20;
  touch-action: none;
  cursor: crosshair;
}

.face-scene canvas.interaction.is-erasing {
  cursor: cell;
}

.confetti {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  pointer-events: none;
  z-index: 30;
}

.canvas-hint {
  position: absolute;
  left: 50%;
  bottom: 14px;
  z-index: 25;
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 7px 12px;
  border: 1px solid rgba(255, 233, 236, 0.16);
  border-radius: 999px;
  background: rgba(18, 6, 12, 0.55);
  color: rgba(255, 239, 236, 0.82);
  font-size: 9.5px;
  font-weight: 500;
  letter-spacing: 0.03em;
  white-space: nowrap;
  backdrop-filter: blur(8px);
  transform: translateX(-50%);
  transition: opacity 0.4s, transform 0.4s;
  pointer-events: none;
}

.canvas-hint span {
  color: var(--gold);
}

.canvas-hint.is-hidden {
  opacity: 0;
  transform: translate(-50%, 8px);
}

.glow-ring {
  position: absolute;
  inset: -12%;
  z-index: -1;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(255, 123, 156, 0.12), transparent 62%);
  pointer-events: none;
}

.stage-footer {
  flex: 0 0 auto;
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 6px;
  padding-top: 9px;
}

.footer-button {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  min-height: 34px;
  padding: 7px 6px;
  border: 1px solid rgba(255, 224, 235, 0.1);
  border-radius: 11px;
  background: rgba(255, 244, 238, 0.04);
  color: #dcc1c8;
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.02em;
  transition: background 0.18s, border-color 0.18s, color 0.18s;
}

.footer-button svg {
  width: 15px;
  height: 15px;
}

.footer-button:hover {
  border-color: rgba(255, 224, 235, 0.24);
  background: rgba(255, 244, 238, 0.08);
  color: var(--cream);
}

.footer-button.danger-soft:hover {
  border-color: rgba(255, 143, 159, 0.4);
  color: #ffc0c8;
}

.mobile-tabs {
  display: none;
}

/* ---------- Client card ---------- */

.client-card {
  position: relative;
  overflow: hidden;
  margin-bottom: 13px;
  padding: 15px;
  border: 1px solid rgba(255, 224, 235, 0.13);
  border-radius: 18px;
  background:
    radial-gradient(circle at 100% 0%, rgba(255, 123, 156, 0.18), transparent 48%),
    linear-gradient(155deg, rgba(93, 34, 61, 0.45), rgba(36, 14, 26, 0.4));
}

.client-card::after {
  content: "";
  position: absolute;
  right: -44px;
  top: -56px;
  width: 140px;
  height: 140px;
  border: 1px solid rgba(255, 255, 255, 0.06);
  border-radius: 50%;
  pointer-events: none;
}

.client-head {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 10px;
}

.avatar {
  display: grid;
  place-items: center;
  flex: 0 0 auto;
  width: 43px;
  height: 43px;
  border: 1px solid rgba(255, 255, 255, 0.28);
  border-radius: 50%;
  background: linear-gradient(145deg, var(--avatar-a, #ff9bb3), var(--avatar-b, #9a3154));
  color: #2a0814;
  font-family: var(--font-display);
  font-size: 15px;
  font-weight: 700;
  box-shadow: 0 8px 22px rgba(0, 0, 0, 0.28), inset 0 1px 0 rgba(255, 255, 255, 0.4);
}

.client-meta {
  min-width: 0;
  flex: 1;
}

.client-meta .mini-label {
  display: block;
  color: var(--gold);
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.18em;
  text-transform: uppercase;
}

.client-meta h3 {
  margin: 1px 0 1px;
  font-family: var(--font-display);
  font-size: 20px;
  font-weight: 500;
}

.client-tagline {
  margin: 0;
  color: var(--muted-2);
  font-size: 9.5px;
}

.score-ring {
  --p: 0;
  position: relative;
  display: grid;
  place-items: center;
  flex: 0 0 auto;
  width: 48px;
  height: 48px;
  border-radius: 50%;
  background: conic-gradient(var(--gold) calc(var(--p) * 1%), rgba(255, 255, 255, 0.09) 0);
  transition: background 0.4s;
}

.score-ring::before {
  content: "";
  position: absolute;
  inset: 5px;
  border-radius: 50%;
  background: #2b1020;
}

.score-ring span {
  position: relative;
  color: #ffeadf;
  font-size: 10px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}

.client-quote {
  position: relative;
  margin: 0 0 12px;
  padding: 0 0 0 11px;
  border-left: 2px solid rgba(255, 123, 156, 0.5);
  color: #e4ccd1;
  font-family: var(--font-display);
  font-size: 11.5px;
  font-style: italic;
  line-height: 1.5;
}

.req-list {
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.req-row {
  display: grid;
  grid-template-columns: 9px minmax(0, 1fr) 48px 14px;
  align-items: center;
  gap: 7px;
  width: 100%;
  padding: 7px 8px;
  border: 1px solid rgba(255, 224, 235, 0.07);
  border-radius: 9px;
  background: rgba(17, 6, 12, 0.26);
  color: #e6cfd4;
  text-align: left;
  transition: background 0.18s, border-color 0.18s;
}

.req-row:hover {
  border-color: rgba(255, 224, 235, 0.18);
  background: rgba(255, 244, 238, 0.055);
}

.req-dot {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: var(--c, #fff);
  box-shadow: 0 0 0 2px rgba(255, 255, 255, 0.12);
}

.req-label {
  overflow: hidden;
  font-size: 9.5px;
  font-weight: 600;
  white-space: nowrap;
  text-overflow: ellipsis;
}

.req-meter {
  height: 3px;
  overflow: hidden;
  border-radius: 99px;
  background: rgba(255, 255, 255, 0.09);
}

.req-meter i {
  display: block;
  height: 100%;
  width: 0;
  border-radius: inherit;
  background: linear-gradient(90deg, var(--rose), var(--gold));
  transition: width 0.45s ease;
}

.req-check {
  color: var(--mint);
  font-size: 11px;
  font-weight: 800;
  opacity: 0;
  transform: scale(0.6);
  transition: opacity 0.2s, transform 0.2s;
}

.req-row.is-done .req-check {
  opacity: 1;
  transform: scale(1);
}

.req-row.is-done {
  border-color: rgba(143, 229, 207, 0.26);
  background: rgba(72, 148, 126, 0.1);
}

.client-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  margin-top: 11px;
}

.client-foot small {
  color: var(--muted-2);
  font-size: 8.5px;
}

.mini-button {
  padding: 6px 9px;
  border: 1px solid rgba(255, 224, 235, 0.14);
  border-radius: 8px;
  background: rgba(255, 244, 238, 0.05);
  color: #ecd5d9;
  font-size: 9px;
  font-weight: 600;
}

.mini-button:hover {
  background: rgba(255, 244, 238, 0.1);
}

.free-card .client-head {
  margin-bottom: 8px;
}

.free-card .client-meta h3 {
  font-size: 24px;
}

.free-tips {
  display: flex;
  flex-direction: column;
  gap: 7px;
  margin-top: 4px;
}

.free-tip {
  display: flex;
  align-items: flex-start;
  gap: 8px;
  color: #d5b7c1;
  font-size: 9.5px;
  line-height: 1.45;
}

.free-tip span {
  color: var(--gold);
  font-size: 11px;
}

/* ---------- Palette ---------- */

.palette-card {
  margin-bottom: 13px;
  padding: 14px;
  border: 1px solid rgba(255, 224, 235, 0.1);
  border-radius: 18px;
  background: rgba(24, 9, 17, 0.3);
}

.palette-heading {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 10px;
  margin-bottom: 11px;
}

.palette-heading h3 {
  font-size: 18px;
}

.current-color {
  display: flex;
  align-items: center;
  gap: 6px;
  color: var(--muted);
  font-size: 9px;
  font-weight: 600;
}

#currentColorChip {
  width: 17px;
  height: 17px;
  border: 1px solid rgba(255, 255, 255, 0.45);
  border-radius: 50%;
  background: #d94862;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.32);
}

.swatches {
  display: grid;
  grid-template-columns: repeat(6, minmax(0, 1fr));
  gap: 7px;
}

.swatch {
  position: relative;
  aspect-ratio: 1;
  width: 100%;
  padding: 0;
  border: 1px solid rgba(255, 255, 255, 0.18);
  border-radius: 50%;
  background: var(--c);
  box-shadow: inset 0 2px 4px rgba(255, 255, 255, 0.25), inset 0 -3px 5px rgba(0, 0, 0, 0.18);
  transition: transform 0.16s, box-shadow 0.16s;
}

.swatch:hover {
  transform: scale(1.1);
}

.swatch.is-active {
  box-shadow:
    0 0 0 2px #2a1020,
    0 0 0 4px var(--gold),
    inset 0 2px 4px rgba(255, 255, 255, 0.28);
  transform: scale(1.05);
}

.swatch.is-active::after {
  content: "";
  position: absolute;
  inset: 0;
  margin: auto;
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: rgba(20, 4, 10, 0.72);
}

.actions-card {
  display: flex;
  flex-direction: column;
  gap: 7px;
}

/* ---------- Buttons ---------- */

.btn-primary {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-height: 43px;
  padding: 11px 20px;
  overflow: hidden;
  border: 1px solid rgba(255, 240, 210, 0.52);
  border-radius: 12px;
  background: linear-gradient(135deg, #ffe3b8 0%, #f1c675 42%, #e7a48e 100%);
  color: #3a0d1d;
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.04em;
  box-shadow: 0 10px 26px rgba(217, 75, 114, 0.2), inset 0 1px 0 rgba(255, 255, 255, 0.7);
  transition: transform 0.18s, box-shadow 0.18s, filter 0.18s;
}

.btn-primary::after {
  content: "";
  position: absolute;
  top: -60%;
  left: -70%;
  width: 40%;
  height: 220%;
  background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.46), transparent);
  transform: rotate(22deg);
  transition: left 0.55s ease;
}

.btn-primary:hover {
  transform: translateY(-1px);
  filter: brightness(1.04);
  box-shadow: 0 14px 30px rgba(217, 75, 114, 0.28), inset 0 1px 0 rgba(255, 255, 255, 0.7);
}

.btn-primary:hover::after {
  left: 130%;
}

.btn-primary:active {
  transform: translateY(0) scale(0.985);
}

.btn-primary.wide {
  width: 100%;
}

.btn-ghost {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 40px;
  padding: 10px 18px;
  border: 1px solid rgba(255, 224, 235, 0.18);
  border-radius: 12px;
  background: rgba(255, 244, 238, 0.045);
  color: #f0d9dc;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.03em;
  transition: background 0.18s, border-color 0.18s, transform 0.18s;
}

.btn-ghost:hover {
  background: rgba(255, 244, 238, 0.09);
  border-color: rgba(255, 224, 235, 0.3);
}

.btn-ghost:active {
  transform: scale(0.985);
}

.btn-ghost.wide {
  width: 100%;
}

.text-button {
  padding: 8px 5px;
  border: 0;
  background: none;
  color: #d9bcc5;
  font-size: 11px;
  font-weight: 600;
  text-decoration: underline;
  text-decoration-color: rgba(255, 224, 235, 0.25);
  text-underline-offset: 4px;
}

.text-button:hover {
  color: var(--cream);
}

/* ---------- Landing ---------- */

.landing {
  position: fixed;
  inset: 0;
  z-index: 50;
  overflow: auto;
  background:
    radial-gradient(circle at 78% 18%, rgba(255, 123, 156, 0.2), transparent 36%),
    radial-gradient(circle at 8% 90%, rgba(185, 151, 255, 0.14), transparent 42%),
    linear-gradient(145deg, #170810, #0f050a 48%, #1d0915);
  transition: opacity 0.45s ease, visibility 0.45s ease;
}

.landing.is-leaving {
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
}

.landing-aurora {
  position: fixed;
  inset: -20%;
  pointer-events: none;
  background:
    conic-gradient(from 180deg at 60% 45%, rgba(255, 123, 156, 0.08), transparent 32%, rgba(241, 198, 117, 0.07) 58%, transparent 76%),
    radial-gradient(circle at 65% 40%, rgba(255, 153, 179, 0.11), transparent 46%);
  filter: blur(22px);
  animation: auroraDrift 18s ease-in-out infinite alternate;
}

.landing-inner {
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(340px, 0.8fr);
  align-items: center;
  gap: clamp(30px, 5vw, 90px);
  width: min(1260px, 100%);
  min-height: 100dvh;
  margin: 0 auto;
  padding: clamp(28px, 6vh, 70px) clamp(24px, 5vw, 68px);
}

.landing-copy {
  max-width: 610px;
  animation: fadeUp 0.8s cubic-bezier(0.2, 0.75, 0.3, 1) both;
}

.eyebrow {
  display: flex;
  align-items: center;
  gap: 10px;
  margin: 0 0 18px;
  color: var(--gold);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.24em;
  text-transform: uppercase;
}

.eyebrow span {
  width: 28px;
  height: 1px;
  background: linear-gradient(90deg, transparent, var(--gold));
}

.landing-title {
  margin: 0;
  font-family: var(--font-display);
  font-size: clamp(78px, 11vw, 148px);
  font-weight: 400;
  line-height: 0.82;
  letter-spacing: -0.045em;
}

.landing-title span {
  display: block;
  color: #fff4ec;
  text-shadow: 0 10px 40px rgba(255, 184, 200, 0.13);
}

.landing-title em {
  display: block;
  margin-left: 0.62em;
  padding-bottom: 0.08em;
  background: linear-gradient(105deg, #ffd8b5 4%, #f1c675 30%, #ff8ba8 64%, #c788ff 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  font-style: italic;
  filter: drop-shadow(0 10px 34px rgba(255, 123, 156, 0.18));
}

.tagline {
  max-width: 440px;
  margin: 28px 0 22px;
  color: #dcc0c7;
  font-family: var(--font-display);
  font-size: clamp(17px, 1.55vw, 21px);
  line-height: 1.55;
}

.feature-list {
  display: flex;
  flex-direction: column;
  gap: 0;
  max-width: 470px;
  margin: 0 0 30px;
  padding: 0;
  list-style: none;
  border-top: 1px solid rgba(255, 224, 235, 0.1);
}

.feature-list li {
  display: grid;
  grid-template-columns: 36px 1fr;
  align-items: baseline;
  gap: 10px;
  padding: 10px 0;
  border-bottom: 1px solid rgba(255, 224, 235, 0.075);
  color: #a98b97;
  font-size: 10.5px;
  line-height: 1.45;
}

.feature-list li span {
  color: rgba(241, 198, 117, 0.66);
  font-family: var(--font-display);
  font-size: 12px;
  font-style: italic;
}

.feature-list li b {
  margin-right: 5px;
  color: #f4dde1;
  font-weight: 600;
}

.landing-actions {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 10px;
}

.landing-play {
  min-height: 54px;
  padding: 13px 28px;
  font-size: 13px;
}

.landing-play small {
  display: none;
}

.landing-note {
  margin: 20px 0 0;
  color: #7e6570;
  font-size: 9px;
  letter-spacing: 0.04em;
}

.landing-art {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  min-height: 620px;
  animation: fadeUp 1s 0.14s cubic-bezier(0.2, 0.75, 0.3, 1) both;
}

.arch-wrap {
  position: relative;
  width: min(390px, 82%);
  animation: floatArt 7s ease-in-out infinite;
}

.arch-glow {
  position: absolute;
  inset: 8% -14% -8%;
  z-index: -1;
  border-radius: 50%;
  background:
    radial-gradient(circle at 50% 46%, rgba(255, 123, 156, 0.3), transparent 54%),
    radial-gradient(circle at 68% 76%, rgba(185, 151, 255, 0.16), transparent 48%);
  filter: blur(26px);
}

.arch {
  position: relative;
  overflow: hidden;
  width: 100%;
  aspect-ratio: 900 / 1150;
  border: 1px solid rgba(255, 239, 242, 0.28);
  border-radius: 999px 999px 28px 28px;
  background: #2b1020;
  box-shadow:
    0 50px 120px rgba(0, 0, 0, 0.62),
    0 0 0 7px rgba(255, 221, 232, 0.035),
    inset 0 0 0 1px rgba(255, 255, 255, 0.08);
}

.arch canvas {
  display: block;
  width: 100%;
  height: 100%;
  transform: scale(1.035);
}

.arch-sheen {
  position: absolute;
  inset: 0;
  background:
    linear-gradient(115deg, rgba(255, 255, 255, 0.22) 0%, transparent 22%, transparent 70%, rgba(255, 255, 255, 0.08) 100%),
    linear-gradient(0deg, rgba(20, 4, 12, 0.48), transparent 22%);
  pointer-events: none;
}

.floating-tag {
  position: absolute;
  display: flex;
  align-items: center;
  gap: 7px;
  padding: 8px 12px;
  border: 1px solid rgba(255, 236, 240, 0.18);
  border-radius: 999px;
  background: rgba(35, 13, 24, 0.72);
  color: #f0d7dc;
  font-size: 9.5px;
  font-weight: 600;
  letter-spacing: 0.03em;
  box-shadow: 0 12px 30px rgba(0, 0, 0, 0.32);
  backdrop-filter: blur(12px);
  white-space: nowrap;
}

.floating-tag span {
  color: var(--gold);
}

.tag-one {
  top: 12%;
  right: -13%;
  animation: floatTag 6s ease-in-out infinite;
}

.tag-two {
  top: 48%;
  left: -18%;
  animation: floatTag 7s 0.8s ease-in-out infinite;
}

.tag-three {
  right: -8%;
  bottom: 13%;
  animation: floatTag 6.5s 0.4s ease-in-out infinite;
}

.landing-orbit {
  position: absolute;
  border: 1px solid rgba(255, 224, 235, 0.07);
  border-radius: 50%;
  pointer-events: none;
}

.orbit-one {
  width: 520px;
  height: 520px;
  transform: rotate(-18deg) scaleY(1.25);
}

.orbit-two {
  width: 660px;
  height: 660px;
  transform: rotate(22deg) scaleY(1.35);
  border-color: rgba(241, 198, 117, 0.06);
}

/* ---------- Modals ---------- */

.modal {
  position: fixed;
  inset: 0;
  z-index: 90;
  display: grid;
  place-items: center;
  padding: 20px;
  visibility: hidden;
  opacity: 0;
  transition: opacity 0.25s ease, visibility 0.25s ease;
}

.modal.is-open {
  visibility: visible;
  opacity: 1;
}

.modal-backdrop {
  position: absolute;
  inset: 0;
  background: rgba(9, 2, 6, 0.72);
  backdrop-filter: blur(12px);
}

.modal-card {
  position: relative;
  z-index: 1;
  width: min(760px, 100%);
  max-height: min(88dvh, 900px);
  margin: auto;
  padding: clamp(18px, 3vw, 30px);
  overflow: auto;
  border: 1px solid rgba(255, 224, 235, 0.17);
  border-radius: 24px;
  background:
    radial-gradient(circle at 100% 0%, rgba(255, 123, 156, 0.13), transparent 42%),
    linear-gradient(155deg, #351628, #1c0a14 72%);
  box-shadow: 0 40px 120px rgba(0, 0, 0, 0.66), inset 0 1px 0 rgba(255, 255, 255, 0.06);
  transform: translateY(14px) scale(0.985);
  transition: transform 0.3s cubic-bezier(0.2, 0.75, 0.3, 1);
}

.modal.is-open .modal-card {
  transform: translateY(0) scale(1);
}

.modal-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 8px;
}

.modal-head h2 {
  font-size: clamp(26px, 4vw, 38px);
}

.modal-sub {
  max-width: 560px;
  margin: 0 0 20px;
  color: var(--muted-2);
  font-size: 11px;
  line-height: 1.5;
}

.modal-close {
  flex: 0 0 auto;
  font-size: 14px;
}

/* Challenge grid */

.challenge-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 11px;
}

.challenge-tile {
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 9px;
  padding: 15px;
  overflow: hidden;
  border: 1px solid rgba(255, 224, 235, 0.11);
  border-radius: 17px;
  background:
    radial-gradient(circle at 100% 0%, color-mix(in srgb, var(--accent) 22%, transparent), transparent 46%),
    rgba(24, 9, 17, 0.42);
  text-align: left;
  transition: transform 0.18s, border-color 0.18s, background 0.18s;
}

.challenge-tile:hover {
  transform: translateY(-2px);
  border-color: rgba(255, 224, 235, 0.28);
  background:
    radial-gradient(circle at 100% 0%, color-mix(in srgb, var(--accent) 30%, transparent), transparent 48%),
    rgba(30, 12, 22, 0.56);
}

.challenge-tile.is-current {
  border-color: color-mix(in srgb, var(--accent) 65%, white 10%);
  box-shadow: 0 0 0 1px color-mix(in srgb, var(--accent) 34%, transparent);
}

.tile-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.tile-client {
  display: flex;
  align-items: center;
  gap: 8px;
}

.tile-avatar {
  display: grid;
  place-items: center;
  width: 30px;
  height: 30px;
  border-radius: 50%;
  background: linear-gradient(145deg, color-mix(in srgb, var(--accent) 75%, white 18%), color-mix(in srgb, var(--accent) 65%, #220914));
  color: #2a0814;
  font-size: 9px;
  font-weight: 800;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.4);
}

.tile-client b {
  display: block;
  font-size: 10px;
  font-weight: 700;
}

.tile-client small {
  display: block;
  margin-top: 1px;
  color: var(--muted-2);
  font-size: 8px;
}

.tile-stars {
  color: rgba(255, 255, 255, 0.15);
  font-size: 12px;
  letter-spacing: 1px;
}

.tile-stars .on {
  color: var(--gold);
  text-shadow: 0 0 10px rgba(241, 198, 117, 0.45);
}

.challenge-tile h3 {
  margin: 0;
  font-family: var(--font-display);
  font-size: 20px;
  font-weight: 500;
}

.challenge-tile p {
  display: -webkit-box;
  margin: 0;
  overflow: hidden;
  color: #c2a5af;
  font-size: 9.5px;
  line-height: 1.45;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
}

.tile-palette {
  display: flex;
  gap: 4px;
}

.tile-palette span {
  width: 13px;
  height: 13px;
  border: 1px solid rgba(255, 255, 255, 0.25);
  border-radius: 50%;
  background: var(--c);
}

.tile-cta {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: 2px;
  color: color-mix(in srgb, var(--accent) 74%, white 20%);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

/* Model modal */

.model-section {
  margin-bottom: 18px;
}

.model-section h3 {
  margin: 0 0 9px;
  color: var(--muted);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.16em;
  text-transform: uppercase;
}

.swatch-row {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.model-swatch {
  position: relative;
  width: 34px;
  height: 34px;
  padding: 0;
  border: 2px solid transparent;
  border-radius: 50%;
  background: var(--c);
  box-shadow: inset 0 2px 4px rgba(255, 255, 255, 0.25), inset 0 -3px 5px rgba(0, 0, 0, 0.2);
  transition: transform 0.16s, border-color 0.16s;
}

.model-swatch:hover {
  transform: scale(1.08);
}

.model-swatch.is-active {
  border-color: #2a1020;
  box-shadow: 0 0 0 2px var(--gold), inset 0 2px 4px rgba(255, 255, 255, 0.25);
}

.style-options,
.backdrop-options {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.style-option {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 100px;
  padding: 10px 13px;
  border: 1px solid rgba(255, 224, 235, 0.13);
  border-radius: 12px;
  background: rgba(255, 244, 238, 0.035);
  text-align: left;
  transition: border-color 0.18s, background 0.18s;
}

.style-option b {
  font-size: 10.5px;
  font-weight: 600;
}

.style-option small {
  color: var(--muted-2);
  font-size: 8.5px;
}

.style-option:hover {
  background: rgba(255, 244, 238, 0.07);
}

.style-option.is-active {
  border-color: rgba(255, 123, 156, 0.66);
  background: rgba(255, 123, 156, 0.12);
}

.backdrop-option {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 7px 11px 7px 7px;
  border: 1px solid rgba(255, 224, 235, 0.13);
  border-radius: 999px;
  background: rgba(255, 244, 238, 0.035);
  font-size: 9.5px;
  font-weight: 600;
  transition: border-color 0.18s, background 0.18s;
}

.backdrop-option .bd-dots {
  display: flex;
}

.backdrop-option .bd-dots span {
  width: 13px;
  height: 13px;
  margin-left: -3px;
  border: 1px solid rgba(255, 255, 255, 0.3);
  border-radius: 50%;
  background: var(--c);
}

.backdrop-option .bd-dots span:first-child {
  margin-left: 0;
}

.backdrop-option:hover {
  background: rgba(255, 244, 238, 0.07);
}

.backdrop-option.is-active {
  border-color: rgba(241, 198, 117, 0.64);
  background: rgba(241, 198, 117, 0.1);
}

/* How to */

.how-steps {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
  margin: 18px 0;
}

.how-step {
  display: flex;
  gap: 11px;
  padding: 13px;
  border: 1px solid rgba(255, 224, 235, 0.1);
  border-radius: 14px;
  background: rgba(18, 6, 12, 0.28);
}

.how-step > span {
  display: grid;
  place-items: center;
  flex: 0 0 auto;
  width: 27px;
  height: 27px;
  border: 1px solid rgba(241, 198, 117, 0.36);
  border-radius: 50%;
  color: var(--gold);
  font-family: var(--font-display);
  font-size: 13px;
}

.how-step h3 {
  margin: 1px 0 4px;
  font-size: 11px;
  font-weight: 700;
}

.how-step p {
  margin: 0;
  color: var(--muted-2);
  font-size: 9.5px;
  line-height: 1.45;
}

.how-tip {
  margin: 0 0 18px;
  padding: 11px 13px;
  border: 1px solid rgba(241, 198, 117, 0.18);
  border-radius: 12px;
  background: rgba(241, 198, 117, 0.06);
  color: #e2c9b2;
  font-size: 10px;
  line-height: 1.5;
}

/* Result */

.result-card {
  width: min(520px, 100%);
  text-align: center;
}

.result-kicker {
  margin: 0 0 8px;
  color: var(--gold);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.22em;
  text-transform: uppercase;
}

.result-title {
  margin: 0;
  font-family: var(--font-display);
  font-size: clamp(34px, 6vw, 48px);
  font-weight: 500;
}

.result-quote {
  margin: 9px auto 20px;
  max-width: 390px;
  color: #d6b9c2;
  font-family: var(--font-display);
  font-size: 13px;
  font-style: italic;
  line-height: 1.5;
}

.result-stars {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 9px;
  margin: 10px 0 14px;
  font-size: 45px;
  line-height: 1;
}

.result-stars span {
  color: rgba(255, 255, 255, 0.12);
  transform: scale(0.8);
  transition: transform 0.45s cubic-bezier(0.2, 1.5, 0.4, 1), color 0.35s, filter 0.35s;
}

.result-stars span.on {
  color: var(--gold);
  filter: drop-shadow(0 0 18px rgba(241, 198, 117, 0.4));
  transform: scale(1);
}

.result-stars span:nth-child(1) {
  transition-delay: 0.1s;
}

.result-stars span:nth-child(2) {
  transition-delay: 0.28s;
}

.result-stars span:nth-child(3) {
  transition-delay: 0.46s;
}

.result-score {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  padding: 7px 14px;
  border: 1px solid rgba(255, 224, 235, 0.12);
  border-radius: 999px;
  background: rgba(18, 6, 12, 0.3);
  color: var(--muted);
  font-size: 10px;
}

.result-score b {
  color: var(--cream);
  font-size: 14px;
}

.coin-reward {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  margin: 14px 0 22px;
  color: var(--gold);
  font-size: 12px;
  font-weight: 700;
}

.coin-reward span {
  display: grid;
  place-items: center;
  width: 22px;
  height: 22px;
  border-radius: 50%;
  background: linear-gradient(145deg, #ffe1a1, #d49a3a);
  color: #5a360c;
  font-size: 11px;
}

.result-actions {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 8px;
}

.result-actions .btn-primary {
  grid-column: span 2;
}

.result-mini {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  margin: 16px 0 0;
  color: var(--muted-2);
  font-size: 9px;
}

.result-mini span {
  color: var(--gold);
}

.result-badge {
  display: grid;
  place-items: center;
  width: 74px;
  height: 74px;
  margin: 0 auto 14px;
  border: 1px solid rgba(241, 198, 117, 0.3);
  border-radius: 50%;
  background: radial-gradient(circle at 35% 30%, rgba(255, 228, 182, 0.22), rgba(241, 198, 117, 0.04));
  color: var(--gold);
  font-size: 34px;
  box-shadow: 0 0 50px rgba(241, 198, 117, 0.12);
}

/* Menu */

.menu-card {
  width: min(420px, 100%);
}

.menu-list {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-top: 16px;
}

.menu-item {
  display: flex;
  align-items: center;
  gap: 12px;
  width: 100%;
  padding: 12px;
  border: 1px solid rgba(255, 224, 235, 0.09);
  border-radius: 13px;
  background: rgba(255, 244, 238, 0.03);
  text-align: left;
  transition: background 0.18s, border-color 0.18s;
}

.menu-item:hover {
  border-color: rgba(255, 224, 235, 0.22);
  background: rgba(255, 244, 238, 0.07);
}

.menu-item > span {
  display: grid;
  place-items: center;
  width: 32px;
  height: 32px;
  border: 1px solid rgba(241, 198, 117, 0.24);
  border-radius: 10px;
  color: var(--gold);
  font-family: var(--font-display);
  font-size: 13px;
}

.menu-item b {
  display: block;
  font-size: 11px;
  font-weight: 600;
}

.menu-item small {
  display: block;
  margin-top: 2px;
  color: var(--muted-2);
  font-size: 9px;
}

.menu-item.subtle > span {
  border-color: rgba(255, 143, 159, 0.24);
  color: var(--danger);
}

/* Toast */

.toast {
  position: fixed;
  left: 50%;
  bottom: max(22px, env(safe-area-inset-bottom));
  z-index: 110;
  max-width: min(420px, calc(100vw - 32px));
  padding: 10px 17px;
  border: 1px solid rgba(255, 224, 235, 0.18);
  border-radius: 999px;
  background: rgba(48, 18, 33, 0.93);
  color: #f8e5e7;
  font-size: 10.5px;
  font-weight: 600;
  letter-spacing: 0.02em;
  text-align: center;
  box-shadow: 0 16px 44px rgba(0, 0, 0, 0.44);
  backdrop-filter: blur(14px);
  opacity: 0;
  transform: translate(-50%, 12px);
  pointer-events: none;
  transition: opacity 0.25s, transform 0.25s;
}

.toast.is-visible {
  opacity: 1;
  transform: translate(-50%, 0);
}

/* ---------- Animations ---------- */

@keyframes fadeUp {
  from {
    opacity: 0;
    transform: translateY(20px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes softPulse {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.45;
  }
}

@keyframes floatArt {
  0%,
  100% {
    transform: translateY(0) rotate(-0.4deg);
  }
  50% {
    transform: translateY(-12px) rotate(0.4deg);
  }
}

@keyframes floatTag {
  0%,
  100% {
    transform: translateY(0);
  }
  50% {
    transform: translateY(-8px);
  }
}

@keyframes auroraDrift {
  from {
    transform: rotate(-4deg) scale(1);
  }
  to {
    transform: rotate(5deg) scale(1.06);
  }
}

@keyframes starBurst {
  0% {
    transform: scale(0.2) rotate(-18deg);
    opacity: 0;
  }
  60% {
    transform: scale(1.12) rotate(3deg);
    opacity: 1;
  }
  100% {
    transform: scale(1) rotate(0);
    opacity: 1;
  }
}

/* ---------- Responsive ---------- */

@media (max-width: 1180px) {
  .studio {
    grid-template-columns: 250px minmax(0, 1fr) 300px;
    padding: 12px 14px 16px;
  }

  .panel {
    padding: 14px;
  }

  .tool-tile {
    min-height: 55px;
    padding: 8px;
  }

  .tool-name {
    font-size: 10.5px;
  }

  .swatches {
    grid-template-columns: repeat(6, minmax(0, 1fr));
  }
}

@media (max-width: 980px) {
  body {
    overflow: auto;
  }

  .app {
    height: auto;
    min-height: 100dvh;
  }

  .topbar {
    height: 58px;
    padding: 0 12px;
  }

  .brand-mark {
    width: 34px;
    height: 34px;
  }

  .brand-text {
    font-size: 18px;
  }

  .stat-chip {
    height: 31px;
    padding: 0 9px;
    font-size: 11px;
  }

  .progress-chip {
    display: none;
  }

  .studio {
    display: flex;
    flex-direction: column;
    height: auto;
    min-height: calc(100dvh - 58px);
    padding: 8px 8px calc(12px + env(safe-area-inset-bottom));
    gap: 8px;
  }

  .stage-wrap {
    order: 0;
    flex: 0 0 auto;
    gap: 8px;
  }

  .stage-card {
    flex: 0 0 auto;
    padding: 8px;
    border-radius: 20px;
  }

  .stage-topbar {
    padding: 2px 3px 6px;
  }

  .live-badge {
    padding: 6px 10px;
    font-size: 9px;
  }

  .face-shell {
    flex: 0 0 auto;
    height: calc(100dvh - 430px);
    min-height: 235px;
    max-height: 350px;
  }

  .face-scene {
    height: 100%;
  }

  .stage-footer {
    padding-top: 7px;
  }

  .footer-button {
    min-height: 31px;
    font-size: 8.5px;
    gap: 4px;
  }

  .footer-button svg {
    width: 13px;
    height: 13px;
  }

  .panel {
    display: none;
    flex: 0 0 auto;
    max-height: 34dvh;
    min-height: 0;
    padding: 14px;
    border-radius: 18px;
  }

  .tools-panel {
    order: 2;
  }

  .looks-panel {
    order: 2;
  }

  .studio[data-mobile-view="kit"] .tools-panel {
    display: block;
    animation: fadeUp 0.25s ease both;
  }

  .studio[data-mobile-view="colors"] .looks-panel,
  .studio[data-mobile-view="client"] .looks-panel {
    display: block;
    animation: fadeUp 0.25s ease both;
  }

  .studio[data-mobile-view="colors"] .client-card {
    display: none;
  }

  .studio[data-mobile-view="client"] .palette-card {
    display: none;
  }

  .tool-tabs {
    margin-bottom: 9px;
  }

  .tool-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 6px;
    margin-bottom: 12px;
  }

  .tool-tile {
    min-height: 60px;
    flex-direction: column;
    justify-content: center;
    gap: 4px;
    padding: 7px 4px;
    text-align: center;
  }

  .tool-icon {
    width: 27px;
    height: 27px;
    border-radius: 8px;
  }

  .tool-icon svg {
    width: 17px;
    height: 17px;
  }

  .tool-name {
    font-size: 9px;
  }

  .tool-sub {
    display: none;
  }

  .brush-controls {
    padding-top: 9px;
  }

  .tool-hint {
    margin-top: 8px;
    padding: 8px 10px;
    font-size: 9px;
  }

  .mobile-tabs {
