  ctx.fillStyle = bg;
  ctx.fillRect(0, 0, WIDTH, HEIGHT + 100);
  for (const id of LAYER_IDS) ctx.drawImage(layers[id], 0, 0);
  ctx.fillStyle = 'rgba(255,255,255,0.08)';
  ctx.fillRect(0, HEIGHT, WIDTH, 1);
  ctx.fillStyle = '#fff1ea';
