  ctx.fillStyle = '#f1c675';
  ctx.font = '600 17px Inter, system-ui, sans-serif';
  ctx.textAlign = 'right';
  ctx.fillText(challenge ? `Reto · ${challenge.title}` : 'Estudio libre', WIDTH - 42, HEIGHT + 56);
  ctx.fillStyle = 'rgba(255,244,238,0.52)';
