import { createRequire } from 'node:module';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const browser = await chromium.launch({ executablePath: '/home/runner/.cache/ms-playwright/chromium-1248/chrome-linux64/chrome', headless: true, args: ['--no-sandbox'] });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
const errors = [];
page.on('pageerror', (e) => errors.push(e.message));
await page.goto('http://localhost:3002/', { waitUntil: 'load' });
await page.getByLabel('Play').click();
await page.waitForTimeout(700);
const info = await page.evaluate(() => {
  const ids = ['studio','faceShell','faceScene','confetti','faceShell'];
  const rects = {};
  for (const id of ids) { const el = document.getElementById(id); if (el) { const r = el.getBoundingClientRect(); rects[id] = {x:r.x,y:r.y,w:r.width,h:r.height}; } }
  const footer = document.querySelector('.stage-footer').getBoundingClientRect();
  const buttons = [...document.querySelectorAll('.footer-button')].map(b=>{const r=b.getBoundingClientRect();return {t:b.textContent.trim(),x:r.x,w:r.width}});
  return { rects, footer:{x:footer.x,w:footer.width}, buttons };
});
console.log(JSON.stringify(info,null,2));
console.log('errors', errors);
await browser.close();

