await dragFace([[380, 790], [420, 800], [450, 805], [480, 800], [520, 790]]);

// Blush
await page.locator('[data-category="face"]').click();
await page.locator('[data-tool="blush"]').click();
await page.locator('[data-color="#f08a9a"]').click();
await dragFace([[270, 640], [300, 650], [330, 640]]);
await dragFace([[570, 640], [600, 650], [630, 640]]);

await page.waitForTimeout(400);
await page.screenshot({ path: '/tmp/opencode/makeup-desktop.png' });

// Challenge flow
await page.getByRole('button', { name: 'Ver todos los retos' }).click();
await page.waitForTimeout(300);
await page.screenshot({ path: '/tmp/opencode/challenges-modal.png' });
await page.locator('[data-challenge="rose-day"]').click();
await page.waitForTimeout(500);
await page.screenshot({ path: '/tmp/opencode/challenge-studio.png' });
const freeMeasure = await page.evaluate(() => window.__glam.measureCurrent());
console.log('before random', JSON.stringify(freeMeasure));
await page.evaluate(() => window.__glam.randomLook());
