import { createRequire } from 'node:module';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const browser = await chromium.launch({ executablePath: '/home/runner/.cache/ms-playwright/chromium-1248/chrome-linux64/chrome', headless: true, args: ['--no-sandbox'] });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 }, acceptDownloads: true });
const errors = [];
page.on('pageerror', (e) => errors.push(e.message));
page.on('console', (m) => { if (m.type() === 'error') errors.push(m.text()); });
await page.goto('http://localhost:3002/', { waitUntil: 'load' });
await page.getByLabel('Play').click();
await page.waitForTimeout(400);

const rect = async () => page.evaluate(() => {
  const r = document.querySelector('canvas.interaction').getBoundingClientRect();
  return { x: r.x, y: r.y, w: r.width, h: r.height };
});
async function dragFace(points) {
  const r = await rect();
  const toScreen = (x, y) => [r.x + (x / 900) * r.w, r.y + (y / 1150) * r.h];
  const [sx, sy] = toScreen(...points[0]);
  await page.mouse.move(sx, sy);
  await page.mouse.down();
  for (const p of points.slice(1)) {
    const [px, py] = toScreen(...p);
    await page.mouse.move(px, py, { steps: 10 });
  }
  await page.mouse.up();
}
const historyState = () => page.evaluate(() => ({
  undo: !document.getElementById('undoBtn').disabled,
  redo: !document.getElementById('redoBtn').disabled,
}));

console.log('history initial', await historyState());
// Paint lipstick
await page.locator('[data-category="lips"]').click();
await page.locator('[data-tool="lipstick"]').click();
await page.locator('[data-color="#c8102e"]').click();
await dragFace([[375, 745], [420, 750], [450, 755], [480, 750], [525, 745]]);
await dragFace([[380, 790], [420, 800], [450, 805], [480, 800], [520, 790]]);
await page.waitForTimeout(250);
console.log('history after paint', await historyState());
const pixelAfterPaint = await page.evaluate(() => {
  const c = document.querySelector('canvas.interaction');
  return c.width;
});
// Undo
await page.locator('#undoBtn').click();
await page.waitForTimeout(150);
console.log('history after undo', await historyState());
await page.locator('#redoBtn').click();
await page.waitForTimeout(150);
console.log('history after redo', await historyState());

// Eraser
await page.locator('[data-category="extra"]').click();
await page.locator('[data-tool="eraser"]').click();
await dragFace([[440, 760], [460, 760]]);
await page.waitForTimeout(150);
console.log('history after erase', await historyState());

// Save photo download
await page.locator('#clearBtn').click();
await page.waitForTimeout(300);
const downloadPromise = page.waitForEvent('download', { timeout: 8000 }).catch(() => null);
await page.locator('#saveBtn').click();
const download = await downloadPromise;
console.log('download', download ? download.suggestedFilename() : 'none');

// Model modal
await page.locator('#modelBtn').click();
await page.waitForTimeout(250);
const skinCount = await page.locator('#skinSwatches button').count();
const hairCount = await page.locator('#hairSwatches button').count();
const eyeCount = await page.locator('#eyeSwatches button').count();
const styleCount = await page.locator('#styleOptions button').count();
const backdropCount = await page.locator('#backdropOptions button').count();
console.log('model options', { skinCount, hairCount, eyeCount, styleCount, backdropCount });
await page.locator('#skinSwatches button').nth(3).click();
await page.locator('#hairSwatches button').nth(4).click();
await page.locator('#styleOptions button').nth(2).click();
await page.locator('#backdropOptions button').nth(2).click();
await page.waitForTimeout(250);
await page.screenshot({ path: '/tmp/opencode/model-modal.png' });
await page.locator('#modelModal .modal-close').click();
await page.waitForTimeout(400);
await page.screenshot({ path: '/tmp/opencode/customized.png' });

// Free palette
await page.locator('[data-category="eyes"]').click();
await page.locator('[data-tool="eyeshadow"]').click();
await page.locator('[data-color="#2ba9b0"]').click();
const chip = await page.locator('#currentColorName').textContent();
console.log('palette chip', chip);

// Challenge flow via modal
await page.getByRole('button', { name: 'Ver todos los retos' }).click();
await page.locator('[data-challenge="classic-red"]').click();
await page.waitForTimeout(500);
const challengeInfo = await page.evaluate(() => ({
  challenge: window.__glam.state.challengeId,
  label: document.getElementById('lookLabel').textContent,
  presentVisible: !document.getElementById('presentBtn').hidden,
  randomVisible: !document.getElementById('randomBtn2').hidden,
}));
console.log('challenge', challengeInfo);
// Use hint chip for lipstick and paint
await page.locator('[data-req-tool="lipstick"]').first().click();
await page.waitForTimeout(200);
await dragFace([[370, 740], [420, 748], [450, 755], [480, 748], [530, 740]]);
await dragFace([[375, 795], [420, 805], [450, 810], [480, 805], [525, 795]]);
await page.waitForTimeout(250);
let m = await page.evaluate(() => window.__glam.measureCurrent());
console.log('after lip paint', JSON.stringify(m));
// Complete remaining reqs through debug apply for speed
await page.evaluate(() => {
  const ch = window.__glam.state.challengeId;
  const c = window.__glam.state.challenges.find((x) => x.id === ch);
  c.reqs.forEach((r) => window.__glam.applyRequirement({ tool: r.tool, color: r.color }));
});
await page.waitForTimeout(300);
m = await page.evaluate(() => window.__glam.measureCurrent());
console.log('complete look', JSON.stringify(m));
await page.screenshot({ path: '/tmp/opencode/challenge-complete.png' });
await page.getByRole('button', { name: 'Presentar look' }).click();
await page.waitForTimeout(700);
const result = await page.evaluate(() => {
  const card = document.getElementById('resultCard');
  const stars = document.querySelectorAll('.result-stars .on').length;
  return { text: card.innerText.replace(/\n+/g, ' | '), stars, visible: document.getElementById('resultModal').classList.contains('is-open') };
});
console.log('result', JSON.stringify(result));
await page.locator('#resultModal .modal-close, #resultModal [data-close]').first().click().catch(() => {});
await page.waitForTimeout(300);

// Persistence: reload
await page.reload({ waitUntil: 'load' });
await page.waitForTimeout(500);
const persisted = await page.evaluate(() => {
  const raw = localStorage.getItem('glam-studio-v1');
  return raw ? JSON.parse(raw) : null;
});
console.log('storage', { coins: persisted?.coins, progress: persisted?.progress, model: persisted?.model });
console.log('errors', errors);
await browser.close();

